// Profil — user.
export function ProfileIcon(props: IconProps) {
  return (
    <Base {...props}>
      <circle cx="12" cy="8" r="3.5" />
      <path d="M5 20a7 7 0 0 1 14 0" />
    </Base>
  );
}

// Chevron — expand/collapse affordance for cards (replaces the ▸/▾ glyphs).
export function ChevronIcon({ open = false, ...props }: IconProps & { open?: boolean }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      width={16}
      height={16}
      aria-hidden="true"
      style={{ transform: open ? "rotate(180deg)" : "none", transition: "transform 150ms ease" }}
      {...props}
    >
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

// Empty state — a calm "no data yet" glyph for EmptyState.
